package dev.hoonex.adofai.loaderinstaller;
import android.content.*;import android.content.pm.PackageInstaller;import android.widget.Toast;
public class InstallReceiver extends BroadcastReceiver{
 public void onReceive(Context c,Intent i){int s=i.getIntExtra(PackageInstaller.EXTRA_STATUS,-999);if(s==PackageInstaller.STATUS_PENDING_USER_ACTION){Intent a=i.getParcelableExtra(Intent.EXTRA_INTENT);if(a!=null){a.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);try{c.startActivity(a);}catch(Exception e){Toast.makeText(c,"설치 확인 화면을 열지 못했습니다. 앱에서 다시 시도하세요.",Toast.LENGTH_LONG).show();}}}else{String msg=s==PackageInstaller.STATUS_SUCCESS?"설치 완료":"설치 실패: "+i.getStringExtra(PackageInstaller.EXTRA_STATUS_MESSAGE);c.getSharedPreferences("state",0).edit().putString("install",msg).apply();Toast.makeText(c,msg,Toast.LENGTH_LONG).show();}}
}